Lemma rt_eager_one : forall Σ Σ' c, 1 <= c <= 31 -> sec Σ' = sec Σ -> sec_nres Σ' = sec_nres Σ ->
  (forall c', c' <> c -> pr Σ' c' = pr Σ c') ->
