Lemma rf_mfa_facts : forall r c, reg_wf c r ->
  r_mfa r <= rf_mfa r c /\ rf_mfa r c mod 0x40000 = 0 /\ 4 * (rf_nf r + rf_newc r c) <= rf_mfa r c
